-- =========================================================
-- AA25 — Votación de disfraces de Halloween
-- Base de datos: halloween
--
-- Cómo usarlo: phpMyAdmin → pestaña "Importar" → elegir este archivo → Continuar
-- (o pegar todo el contenido en la pestaña SQL).
--
-- Usuarios de prueba:
--   admin  / Halloween2026!   (administrador)
--   ana    / calabaza123
--   bruno  / calabaza123
--   carla  / calabaza123
-- =========================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";

CREATE DATABASE IF NOT EXISTS halloween DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE halloween;

-- Si ya existían, se recrean (sirve para volver a cargar los datos de prueba)
DROP TABLE IF EXISTS votos;
DROP TABLE IF EXISTS usuarios;
DROP TABLE IF EXISTS disfraces;

-- ---------------------------------------------------------
-- Estructura de tabla para la tabla disfraces
-- (columnas exactamente como pide la consigna)
--   foto      → tipo MIME de la imagen guardada (ej. image/jpeg)
--   foto_blob → bytes de la imagen (BLOB: máximo 64 KB)
--   eliminado → borrado lógico (0 = visible, 1 = eliminado)
-- ---------------------------------------------------------
CREATE TABLE disfraces (
  id int(11) NOT NULL,
  nombre varchar(50) NOT NULL,
  descripcion text NOT NULL,
  votos int(11) NOT NULL,
  foto varchar(20) NOT NULL,
  foto_blob blob NOT NULL,
  eliminado int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------
-- Estructura de tabla para la tabla usuarios
--   clave → hash BCRYPT (password_hash), nunca la contraseña en texto plano
-- ---------------------------------------------------------
CREATE TABLE usuarios (
  id int(11) NOT NULL,
  nombre varchar(50) NOT NULL,
  clave text NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------
-- Estructura de tabla para la tabla votos
-- ---------------------------------------------------------
CREATE TABLE votos (
  id int(11) NOT NULL,
  id_usuario int(11) NOT NULL,
  id_disfraz int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------
-- Índices y AUTO_INCREMENT
-- ---------------------------------------------------------
ALTER TABLE disfraces
  ADD PRIMARY KEY (id);

ALTER TABLE usuarios
  ADD PRIMARY KEY (id),
  ADD UNIQUE KEY uk_usuarios_nombre (nombre);           -- no se repiten nombres de usuario

ALTER TABLE votos
  ADD PRIMARY KEY (id),
  ADD UNIQUE KEY uk_voto_unico (id_usuario, id_disfraz), -- un usuario vota UNA vez cada disfraz
  ADD KEY idx_votos_disfraz (id_disfraz);

ALTER TABLE disfraces MODIFY id int(11) NOT NULL AUTO_INCREMENT;
ALTER TABLE usuarios  MODIFY id int(11) NOT NULL AUTO_INCREMENT;
ALTER TABLE votos     MODIFY id int(11) NOT NULL AUTO_INCREMENT;

-- Integridad referencial: si se borra un usuario se borran sus votos
ALTER TABLE votos
  ADD CONSTRAINT fk_votos_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios (id) ON DELETE CASCADE,
  ADD CONSTRAINT fk_votos_disfraz FOREIGN KEY (id_disfraz) REFERENCES disfraces (id) ON DELETE CASCADE;

